<?php
$root=dirname(__DIR__);
require_once $root.'/app/bootstrap.php';
require_once $root.'/app/MigrationService.php';
MigrationService::run();
require_once $root.'/app/BehaviorService.php';
require_once $root.'/app/CausalService.php';
require_once $root.'/app/StateSyncService.php';
require_once $root.'/app/SimulationService.php';

$action=$_POST['action']??null;$sid=(int)($_GET['simulation']??($_POST['simulation_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        if($action==='create'){$sid=SimulationService::create('CONCEALED_FAILURE',(int)($_POST['duration_seconds']??300));header('Location: ?simulation='.$sid);exit;}
        if($action==='start'){SimulationService::start($sid);header('Location: ?simulation='.$sid);exit;}
        if($action==='advance'){SimulationService::advance($sid,(int)($_POST['seconds']??30));header('Location: ?simulation='.$sid);exit;}
        if($action==='decide'){SimulationService::choose($sid,(int)$_POST['decision_id'],(string)$_POST['option_code']);header('Location: ?simulation='.$sid);exit;}
    }catch(Throwable$e){$error=$e->getMessage();}
}
if($sid>0){try{CausalService::reconcile($sid);StateSyncService::reconcile($sid);}catch(Throwable$e){$error=($error??'').(($error??'')?' | ':'').$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Game2 Story Engine Lab</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#20242b;background:#f3f4f6}*{box-sizing:border-box}body{margin:0}header{position:sticky;top:0;z-index:20;background:#111827;color:white;padding:14px 18px;box-shadow:0 2px 8px #0002}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.brand{font-weight:800}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}button,select{font:inherit;padding:8px 10px;border:1px solid #cbd5e1;border-radius:8px;background:white;color:#111827}button{cursor:pointer}.wrap{padding:16px;min-width:1500px}.setup{max-width:820px;margin:40px auto;background:white;border:1px solid #e5e7eb;border-radius:14px;padding:24px}.grid{display:grid;grid-template-columns:1.15fr repeat(6,1fr);gap:10px;align-items:start}.col{background:#fff;border:1px solid #d9dee7;border-radius:12px;min-height:70vh;overflow:hidden}.col h2{font-size:15px;margin:0;padding:12px 12px 8px;border-bottom:1px solid #e5e7eb;background:#f8fafc}.meta{font-size:12px;padding:10px 12px;border-bottom:1px solid #e5e7eb}.entry{padding:10px 12px;border-bottom:1px solid #eef2f7;font-size:12px;line-height:1.45;white-space:pre-line}.entry strong{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#64748b;margin-bottom:4px}.world .entry{background:#fcfcfd}.factor{display:flex;justify-content:space-between;gap:8px;margin:3px 0}.muted{color:#64748b}.error{background:#fee2e2;color:#991b1b;padding:10px 14px}.phase{font-weight:700}.stats{margin-top:8px;padding-top:8px;border-top:1px dashed #d7dce4}.stat{display:flex;justify-content:space-between;gap:6px}.private{background:#fff7ed;border-left:3px solid #f59e0b;padding:8px;margin-top:8px}.private strong{display:block;margin-bottom:6px}.slot{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#64748b}.empty{padding:18px;color:#64748b;font-size:12px}.decision{margin:10px;border:1px solid #7c3aed;background:#f5f3ff;border-radius:10px;padding:10px;font-size:12px}.decision h3{font-size:13px;margin:0 0 8px}.decision form{margin:6px 0}.decision button{width:100%;text-align:left;background:white}.deadline{font-size:10px;color:#6d28d9;margin-top:6px}.final-state{margin:12px;border:2px solid #0f766e;background:#f0fdfa;border-radius:10px;padding:10px;font-size:12px;line-height:1.5}.final-state h3{margin:0 0 8px;font-size:13px;color:#115e59}.final-state-row{margin:5px 0}.changed{font-weight:700;color:#115e59}.unchanged{color:#64748b;font-size:10px}.final-state .stats{margin-top:8px;padding-top:8px;border-top:1px dashed #99d5cc}</style></head><body>
<?php if(!empty($error))echo '<div class="error">'.e($error).'</div>'; ?>
<?php if(!$sid): ?>
<header><div class="top"><div class="brand">Game2 Story Engine Lab</div></div></header><main class="setup"><h1>New Simulation</h1><p>One shared reality. Different personal stories.</p><form method="post"><input type="hidden" name="action" value="create"><label>Plot<br><select disabled><option>The Storm at Bellweather Resort</option></select></label><br><br><label>Duration<br><select name="duration_seconds"><option value="300">5 minutes</option><option value="900">15 minutes</option></select></label><br><br><button>Create Simulation</button></form></main>
<?php else: $x=SimulationService::snapshot($sid);$sim=$x['simulation'];$players=array_values(array_filter($x['characters'],fn($c)=>$c['actor_type']==='PLAYER'));$npcs=array_values(array_filter($x['characters'],fn($c)=>$c['actor_type']==='NPC'));$orderedCharacters=array_merge($players,$npcs); ?>
<header><div class="top"><div><div class="brand">Game2 Story Engine Lab</div><div style="font-size:12px;color:#cbd5e1"><?=e($sim['title'])?> · <?=e($sim['genre'])?> · <?=e($sim['setting_name'])?></div></div><div class="controls"><span class="phase"><?=e($sim['current_phase'])?></span><span><?=gmdate('i:s',(int)$sim['elapsed_seconds'])?> / <?=gmdate('i:s',(int)$sim['duration_seconds'])?></span><?php if($sim['status']==='READY'): ?><form method="post"><input type="hidden" name="action" value="start"><input type="hidden" name="simulation_id" value="<?=$sid?>"><button>Start</button></form><?php elseif($sim['status']==='RUNNING'): ?><form method="post"><input type="hidden" name="action" value="advance"><input type="hidden" name="simulation_id" value="<?=$sid?>"><input type="hidden" name="seconds" value="30"><button>+30s</button></form><form method="post"><input type="hidden" name="action" value="advance"><input type="hidden" name="simulation_id" value="<?=$sid?>"><input type="hidden" name="seconds" value="60"><button>+60s</button></form><?php endif; ?><form method="post"><input type="hidden" name="action" value="create"><input type="hidden" name="duration_seconds" value="300"><button>New Simulation</button></form></div></div></header>
<div class="wrap"><div class="grid">
<section class="col world"><h2>World</h2><div class="meta"><div><strong>Archetype</strong> <?=e($sim['archetype'])?></div><div style="margin-top:8px"><strong>Story Factors</strong><?php foreach($x['factors'] as$f): ?><div class="factor"><span><?=e($f['label'])?></span><b><?=e($f['current_value'])?></b></div><?php endforeach; ?></div></div><?php foreach($x['world'] as$ev): ?><div class="entry"><strong><?=gmdate('i:s',(int)$ev['event_second'])?> · <?=e($ev['phase'])?> · <?=e($ev['event_type'])?></strong><b><?=e($ev['headline'])?></b><div><?=e($ev['event_text'])?></div><?php if(!empty($ev['actor_name'])): ?><div class="muted">Actor: <?=e($ev['actor_name'])?></div><?php endif; ?></div><?php endforeach; if(!$x['world'])echo '<div class="empty">No world events yet.</div>'; ?></section>
<?php foreach($orderedCharacters as$ch): ?><section class="col"><h2><span class="slot"><?=e($ch['actor_type'])?> <?=e($ch['slot_no'])?></span><br><?=e($ch['name'])?></h2><div class="meta"><div><?=e($ch['description'])?></div><div class="private"><strong>Private Knowledge</strong><?=e($ch['private_knowledge'])?></div><div style="margin-top:8px"><strong>Initial Location</strong> <?=e($ch['initial_location'])?></div><div><strong>Initial Goal</strong> <?=e($ch['initial_goal_text'])?></div><div><strong>Initial Fear</strong> <?=e($ch['initial_fear_text'])?></div><div class="stats"><strong>Initial Stats</strong><?php foreach($ch['stats'] as$st): $iv=$st['initial_value']??$st['current_value']; ?><div class="stat"><span><?=e($st['label'])?></span><b><?=e($iv)?></b></div><?php endforeach; ?></div></div>
<?php if($ch['actor_type']==='PLAYER')foreach($ch['open_decisions'] as$dec): ?><div class="decision"><h3>Decision Available</h3><div><?=e($dec['prompt_text'])?></div><?php foreach($dec['options'] as$o): ?><form method="post"><input type="hidden" name="action" value="decide"><input type="hidden" name="simulation_id" value="<?=$sid?>"><input type="hidden" name="decision_id" value="<?=$dec['decision_id']?>"><input type="hidden" name="option_code" value="<?=e($o['option_code'])?>"><button><?=e($o['label'])?></button></form><?php endforeach; ?><div class="deadline">Open <?=gmdate('i:s',(int)$dec['opens_at_second'])?>–<?=gmdate('i:s',(int)$dec['closes_at_second'])?></div></div><?php endforeach; ?>
<?php foreach($ch['history'] as$h): ?><div class="entry"><strong><?=gmdate('i:s',(int)$h['event_second'])?> · <?=e($h['history_type'])?></strong><b><?=e($h['title'])?></b><div><?=e($h['detail_text'])?></div></div><?php endforeach; ?>
<?php if($sim['status']==='COMPLETE'): $locChanged=$ch['current_location']!==$ch['initial_location'];$goalChanged=$ch['goal_text']!==$ch['initial_goal_text'];$fearChanged=$ch['fear_text']!==$ch['initial_fear_text']; ?><div class="final-state"><h3>Final Character State</h3><div class="final-state-row"><strong>Location</strong> <span class="<?=$locChanged?'changed':''?>"><?=e($locChanged?$ch['initial_location'].' → '.$ch['current_location']:$ch['current_location'])?></span><?php if(!$locChanged): ?> <span class="unchanged">unchanged</span><?php endif; ?></div><div class="final-state-row"><strong>Goal</strong> <span class="<?=$goalChanged?'changed':''?>"><?=e($goalChanged?$ch['initial_goal_text'].' → '.$ch['goal_text']:$ch['goal_text'])?></span><?php if(!$goalChanged): ?> <span class="unchanged">unchanged</span><?php endif; ?></div><div class="final-state-row"><strong>Fear</strong> <span class="<?=$fearChanged?'changed':''?>"><?=e($fearChanged?$ch['initial_fear_text'].' → '.$ch['fear_text']:$ch['fear_text'])?></span><?php if(!$fearChanged): ?> <span class="unchanged">unchanged</span><?php endif; ?></div><div class="stats"><strong>Stats</strong><?php foreach($ch['stats'] as$st): $iv=(int)($st['initial_value']??$st['current_value']);$cv=(int)$st['current_value'];$sc=$iv!==$cv; ?><div class="stat"><span><?=e($st['label'])?></span><b class="<?=$sc?'changed':''?>"><?=e($sc?$iv.' → '.$cv:$cv)?></b><?php if(!$sc): ?><span class="unchanged">unchanged</span><?php endif; ?></div><?php endforeach; ?></div></div><?php endif; ?>
</section><?php endforeach; ?>
</div></div>
<?php endif; ?></body></html>